from __future__ import annotations

import posixpath
import re
import shlex
from pathlib import Path

ENV_KEY = re.compile(r'^[A-Za-z_][A-Za-z0-9_]*$')


def _quote(value):
    return shlex.quote(str(value))


def _docker(kind):
    return 'sudo -n docker' if kind == 'ssh' else 'docker'


def build_script(node_id, node):
    """Build the read-only readiness probe shell script for one environment."""
    probe = node.get('probe') or {}
    kind = node.get('kind', 'wsl')
    lines = [
        '#!/usr/bin/env bash',
        '# generated by training/dashboard/environment_probe.py for ' + str(node_id),
        '# read-only readiness probe; does not start training',
        'set -u',
        'READY=1',
        'pass() { printf "CHECK %s ok %s\\n" "$1" "$2"; }',
        'fail() { READY=0; printf "CHECK %s fail %s\\n" "$1" "$2"; }',
    ]
    python = node.get('python')
    if kind == 'wsl' and python:
        lines.append('if [ -x ' + _quote(python) + ' ]; then pass python ' + _quote(python) + '; else fail python ' + _quote('解释器不存在: ' + python) + '; fi')
    gpu_mode = probe.get('gpu') or ('torch' if kind == 'wsl' else 'nvidia-smi')
    if gpu_mode == 'torch':
        if python:
            code = _quote("import torch;print(torch.cuda.get_device_name(0) if torch.cuda.is_available() else '')")
            lines.append('GPU=$(' + _quote(python) + ' -c ' + code + ' 2>/dev/null) || GPU=')
        else:
            lines.append('GPU=')
        lines.append('if [ -n "$GPU" ]; then pass gpu "$GPU"; else fail gpu "torch.cuda 不可用"; fi')
    else:
        lines.append('GPU=$(nvidia-smi --query-gpu=name --format=csv,noheader 2>/dev/null | head -1)')
        lines.append('if [ -n "$GPU" ]; then pass gpu "$GPU"; else fail gpu "nvidia-smi 无输出"; fi')
    if probe.get('docker'):
        docker = _docker(kind)
        lines.append('DOCKER=$(' + docker + ' info --format "{{.ServerVersion}}" 2>/dev/null) || DOCKER=')
        lines.append('if [ -n "$DOCKER" ]; then pass docker "$DOCKER"; else fail docker "docker daemon 不可用"; fi')
        image = probe.get('image')
        if image:
            lines.append('if ' + docker + ' image inspect ' + _quote(image) + ' >/dev/null 2>&1; then pass image ' + _quote(image) + '; else fail image ' + _quote('镜像不存在: ' + image) + '; fi')
    env_file = node.get('env_file')
    keys = [key for key in (probe.get('env_keys') or []) if ENV_KEY.match(str(key))]
    if env_file and keys:
        lines.append('if [ -f ' + _quote(env_file) + ' ]; then')
        lines.append('  set -a')
        lines.append('  . ' + _quote(env_file) + ' >/dev/null 2>&1 || true')
        lines.append('  set +a')
        for key in keys:
            expression = '$' + '{' + key + '-}'
            lines.append('  if [ -n "' + expression + '" ]; then pass env:' + key + ' "已设置"; else fail env:' + key + ' "未设置"; fi')
        lines.append('else')
        lines.append('  fail env_file ' + _quote('不存在: ' + env_file))
        lines.append('fi')
    if probe.get('benchmark') and node.get('benchmark_root'):
        marker = node['benchmark_root'].rstrip('/') + '/venv/pyvenv.cfg'
        lines.append('if [ -f ' + _quote(marker) + ' ]; then pass benchmark ' + _quote(marker) + '; else fail benchmark ' + _quote('缺少 ' + marker) + '; fi')
    work_root = node.get('work_root')
    if work_root:
        parent = posixpath.dirname(str(work_root).rstrip('/')) or '/'
        lines.append('if [ -d ' + _quote(work_root) + ' ] || [ -w ' + _quote(parent) + ' ]; then pass work_root ' + _quote(work_root) + '; else fail work_root ' + _quote('目录不可写: ' + parent) + '; fi')
    lines.append('printf "DUCK_PROBE_READY %s\\n" "$READY"')
    return '\n'.join(lines) + '\n'


def parse_output(text):
    checks = []
    ready = None
    for line in (text or '').splitlines():
        if line.startswith('CHECK '):
            parts = line.split(' ', 3)
            if len(parts) >= 3:
                checks.append({'name': parts[1], 'ok': parts[2] == 'ok', 'detail': parts[3].strip() if len(parts) > 3 else ''})
        elif line.startswith('DUCK_PROBE_READY '):
            ready = line.rsplit(' ', 1)[-1].strip() == '1'
    failures = [check for check in checks if not check['ok']]
    if ready is None:
        return {'ready': False, 'checks': checks, 'detail': '探测脚本未返回 READY 标记'}
    detail = '；'.join(check['name'] + ': ' + check['detail'] for check in failures) if failures else '就绪'
    return {'ready': bool(ready and not failures), 'checks': checks, 'detail': detail}


def probe_directory(data_dir):
    return Path(data_dir) / 'probes'


def ensure_scripts(data_dir, nodes):
    """Write one generated probe script per registered environment; return paths."""
    directory = probe_directory(data_dir)
    directory.mkdir(parents=True, exist_ok=True)
    paths = {}
    for node_id, node in nodes.items():
        path = directory / (str(node_id) + '.sh')
        text = build_script(node_id, node)
        if not path.exists() or path.read_text(encoding='utf-8') != text:
            path.write_text(text, encoding='utf-8', newline='\n')
        paths[node_id] = path
    return paths
